WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, ship_to, attributes, EXISTS(items, li -> li.price > 100) AS has_premium_item, attributes['device'] AS device, COALESCE(attributes['device'], 'direct') AS device_or_default, ARRAY_CONTAINS(MAP_KEYS(attributes), 'utm_source') AS has_utm_source FROM carts WHERE ARRAY_CONTAINS(coupon_codes, 'VIP')) SELECT *, LAST_VALUE(device_or_default, TRUE) OVER (PARTITION BY customer_id ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_device_or_default, ROW_NUMBER() OVER w_hist event_seq, ROW_NUMBER() OVER (ORDER BY created_at DESC, id) seq_no, FIRST_VALUE(device, TRUE) OVER w_recent first_known_device, LAST_VALUE(device) IGNORE NULLS OVER w_recent last_known_device FROM unpacked WINDOW w_hist AS (PARTITION BY customer_id ORDER BY created_at DESC, id), w_recent AS (ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
